                var userData = await usersClient.AspNetUsersGetUserAsync(model.Username);
                HttpContextAccessor.HttpContext!.Session.Clear();
                PortalApiTokenStore.SetTokens(
                    HttpContextAccessor.HttpContext.Session,
                    response.AccessToken,
                    response.RefreshToken,
                    response.ExpiresIn);

                var photoUrl = PortalUserPhoto.FromObject(userData);
                var identity = new ClaimsIdentity(new[]
                {
                    new Claim(ClaimTypes.NameIdentifier, $"{userData.Id}"),
                    new Claim(ClaimTypes.Name, $"{userData.FirstName} {userData.LastName}"),
                    new Claim(ClaimTypes.Email, userData.Email),
                    new Claim(ClaimTypes.GroupSid, $"{userData.PermissionGroupName}"),
                    new Claim(PortalUserPhoto.ClaimType, photoUrl)
                }, CookieAuthenticationDefaults.AuthenticationScheme);

                var userPrincipal = new ClaimsPrincipal(identity);
                var authProperties = new AuthenticationProperties
                {
                    IsPersistent = false,
                    AllowRefresh = true,
                    ExpiresUtc = DateTimeOffset.UtcNow.AddMinutes(30)
                };
                PortalApiTokenStore.ApplyTokensToProperties(
                    authProperties,
                    response.AccessToken,
                    response.RefreshToken,
                    response.ExpiresIn);

                await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme, userPrincipal,
                    authProperties);

                var redirectUrl = string.IsNullOrEmpty(model.ReturnUrl) || !Url.IsLocalUrl(model.ReturnUrl)
                    ? Url.Action("Index", "Home")
                    : model.ReturnUrl;
                return AuthRedirect(redirectUrl);
