            }
            catch (Exception ex)
            {
                model.ErrorMessage = $"Server Error !!!\nPlease try again later.\nError:{ex.Message}";
                return AuthPage(model, model.ErrorMessage);
            }
            
            return AuthPage(model, model.ErrorMessage);
        }

